// Gorgon V1 — data bridge.
//
// Replaces the script-tag load order of the legacy app
// (data.js -> generated-data.js -> generated-search-demo.js ->
//  data-adapter.js) with explicit ES module imports. The underlying files
// are UNCHANGED and still live in ui_kits/app/ — two of them are pipeline
// artifacts regenerated by `python pipeline/run.py`, so they are imported
// here, never copied.
//
// Adapter rule (same as ui_kits/app/data-adapter.js):
//   - GORGON_GENERATED_DATA exists and is a non-empty array (bare array, or
//     the V3F freshness envelope { generatedAt, activities })
//       -> use pipeline output as the activity list.
//   - otherwise -> keep data.js DEMO DATA untouched (fallback).
// data.js is NEVER overwritten by anyone.
//
// V3F.1: a manually refreshed dataset (gorgon_sync_dataset, written by
// lib/data-sync.js on a successful server pull) is the FRESHEST source and
// wins over the bundled snapshot. The bundled files stay untouched.

import "../../../ui_kits/app/data.js";
import "../../../ui_kits/app/generated-data.js";
import "../../../ui_kits/app/generated-search-demo.js";
import { readCachedDataset, stampDemoFlags } from "./data-sync.js";
// V2.4 hackathon-discovery: curated real hackathon/AI events. ADDITIVE —
// they extend the activity list, never replace any existing source.
import { validatedHackathons } from "../data/hackathons.js";
import { HACKATHONS } from "../data/hackathons.js";

const data = window.GORGON_DATA;
let gen = window.GORGON_GENERATED_DATA;

// V3F B4: unwrap the freshness envelope if present.
if (gen && !Array.isArray(gen) && Array.isArray(gen.activities)) {
  if (gen.generatedAt) data.generatedAt = gen.generatedAt;
  if (gen.dateRange) data.generatedDateRange = gen.dateRange;
  gen = gen.activities;
}

if (Array.isArray(gen) && gen.length > 0 && data && typeof data === "object") {
  data.activities = gen;
  data.generatedFromPipeline = true;
}

// V3F.1: the cached manual refresh (fresher than the bundle) wins. The
// envelope carries its own generatedAt so the freshness note stays honest.
const synced = readCachedDataset();
if (synced && Array.isArray(synced.activities) && synced.activities.length > 0
    && data && typeof data === "object") {
  // V3F.2: cached copies written before the demo stamping fix carry raw
  // records without `demo` — re-stamp on restore so the filter stays honest.
  stampDemoFlags(synced.activities);
  data.activities = synced.activities;
  data.generatedAt = synced.generatedAt || data.generatedAt;
  data.syncedFromServer = true;
}

// V2.4 hackathon-discovery: merge the curated hackathon dataset in LAST.
// Pipeline output / synced dataset / the data.js fallback all stay first;
// hackathons only ADD records (id-deduped) and never remove any. Runs
// regardless of which base is active so discovery works in every mode.
if (data && typeof data === "object" && Array.isArray(data.activities)) {
  const curated = validatedHackathons(HACKATHONS);
  const seen = {};
  data.activities.forEach((a) => { if (a && a.id != null) seen[String(a.id)] = true; });
  const additions = curated.filter((a) => !seen[a.id]);
  if (additions.length) {
    data.activities = data.activities.concat(additions);
    data.hackathonsMerged = true;
  }
}

export const GORGON_DATA = data;
export const GORGON_SEARCH_DEMO = window.GORGON_SEARCH_DEMO || null;
